<template>
  <li>
    <input type="checkbox" v-model="todo.completed" />
    <span :class="{ completed: todo.completed }">{{ todo.text }}</span>
    <button @click="$emit('delete')">✖</button>
  </li>
</template>

<script setup>
defineProps(['todo'])
defineEmits(['delete'])
</script>

// TodoItem.test.js
import { mount } from '@vue/test-utils'
import TodoItem from './TodoItem.vue'

describe('TodoItem', () => {
  const todo = { id: 1, text: 'Learn Vue', completed: false }

  it('renders todo text', () => {
    const wrapper = mount(TodoItem, { props: { todo } })
    expect(wrapper.text()).toContain('Learn Vue')
  })

  it('emits delete when button is clicked', async () => {
    const wrapper = mount(TodoItem, { props: { todo } })
    await wrapper.find('button').trigger('click')
    expect(wrapper.emitted()).toHaveProperty('delete')
  })

  it('applies completed class when completed is true', async () => {
    const completedTodo = { ...todo, completed: true }
    const wrapper = mount(TodoItem, { props: { todo: completedTodo } })
    const span = wrapper.find('span')
    expect(span.classes()).toContain('completed')
  })
})
